-      input, output, indices, packed_output, num_token_non_padded, num_rows, k, renormalize, device)
-  switch (num_experts) {
-    case 1:
-      TSP_LAUNCH(1);
-      break;
-    case 2:
-      TSP_LAUNCH(2);
-      break;
-    case 4:
-      TSP_LAUNCH(4);
-      break;
-    case 8:
-      TSP_LAUNCH(8);
-      break;
-    case 16:
-      TSP_LAUNCH(16);
-      break;
-    case 32:
