+  e = fmaf(e, f * kLn2, 1.0f / 120.0f);
+  e = fmaf(e, f * kLn2, 1.0f / 24.0f);
+  e = fmaf(e, f * kLn2, 1.0f / 6.0f);
+  e = fmaf(e, f * kLn2, 0.5f);
+  e = fmaf(e, f * kLn2, 1.0f);
+  e = fmaf(e, f * kLn2, 1.0f);
