+  const auto d = 2.0f + z;
+  const auto inv0 = ptx::rcp_approx_ftz(d);
+  const auto inv = fmaf(inv0, fmaf(-d, inv0, 1.0f), inv0);
+  const auto s = z * inv;
+  const auto s2 = s * s;
